        joshua(1, 1, "Deuteronomy", 34, 9, "Joshua takes leadership after Moses' death, following the commissioning that filled him with wisdom and secured Israel's obedience to him."),
        joshua(1, 1, "Deuteronomy", 1, 38, "Moses had named Joshua as the one who would lead Israel into the land; this verse begins that succession."),
        joshua(1, 1, "Deuteronomy", 31, 23, "God's command to Joshua to lead Israel into the promised land is carried forward when Joshua assumes leadership after Moses dies."),
        joshua(1, 4, "Genesis", 15, 18, "The land boundaries given to Joshua realize the scope of God's covenant promise to Abraham, from the wilderness toward the Euphrates."),
        joshua(1, 4, "Deuteronomy", 11, 24, "God repeats to Joshua the wilderness-to-Euphrates boundary Moses had set before Israel as the promised inheritance."),
        joshua(1, 4, "Deuteronomy", 1, 7, "Joshua's commission renews the land promise Moses had announced at Horeb, including Lebanon and the Euphrates."),
        joshua(1, 5, "Deuteronomy", 31, 6, "The assurance that God will not leave Israel is now addressed personally to Joshua as he leads the conquest."),
