        judges(7, 25, "Isaiah", 10, 26, "Isaiah recalls the Lord's blow against Midian at the rock of Oreb as a pattern for his promised deliverance."),
        judges(7, 25, "Judges", 8, 3, "The capture of Oreb and Zeeb is the victory Gideon cites when answering Ephraim's complaint."),
        judges(8, 5, "Genesis", 33, 17, "Gideon's pursuit passes through Succoth, the place Jacob named when he settled there after returning to Canaan."),
